<script setup lang="ts">
import {computed} from 'vue';
import {BESTIARY_STAT_KEYS,bestiaryIssues,weaponAttack,type BestiaryCatalog,type BestiaryData,type BestiaryStat,type BestiaryAttack} from '../../../api/src/campaign-bestiary-model';
const props=defineProps<{data:BestiaryData;catalog:BestiaryCatalog;editable?:boolean}>();
const emit=defineEmits<{(e:'update:data',v:BestiaryData):void}>();
const labels:Record<BestiaryStat,string>={movement:'Mouvement (m)',actions:'Actions (PA)',initiative:'Initiative',perception:'Perception',mastery:'Maîtrise',physicalDefense:'Défense physique',occultDefense:'Défense occulte',pv:'PV',armor:'Armure',attack:'Attaque de base'};
const ranges=computed(()=>props.catalog.ranges[`${props.data.difficultyId}:${props.data.archetypeId}`]);
const issues=computed(()=>bestiaryIssues(props.data));
const value=(e:Event)=>(e.target as HTMLInputElement).value;
function patch(v:Partial<BestiaryData>){emit('update:data',{...props.data,...v});}
function stat(k:BestiaryStat,e:Event){patch({stats:{...props.data.stats,[k]:Number(value(e))}});}
function attack(i:number,v:Partial<BestiaryAttack>){const attacks=props.data.attacks.map((a,n)=>n===i?{...a,...v}:a);patch({attacks});}
function weapon(i:number,id:string){const w=props.catalog.weapons.find(w=>w.id===id);const score=props.data.attacks[i].score;attack(i,w?weaponAttack(w,score):{weaponId:''});if(w)patch({attacks:props.data.attacks.map((a,n)=>n===i?weaponAttack(w,score):a),equipment:w.name});}
function group(i:number,group:string){const choices=props.catalog.weapons.filter(w=>w.group===group),w=choices[Math.floor(Math.random()*choices.length)];if(w)weapon(i,w.id);else attack(i,{name:'Coup naturel',damage:2,range:'Contact',properties:'',weaponId:''});}
function list(k:'abilities'|'weaknesses'|'tags',e:Event){patch({[k]:value(e).split('\n').map(s=>s.trim()).filter(Boolean)});}
</script>
<template>
 <div class="creature-sheet">
  <div class="card"><h4>Identité et rencontre</h4><template v-if="editable"><label>Nom de la créature<input :value="data.name" maxlength="120" required @input="patch({name:value($event)})" /></label><div class="grid"><label>Monde<select :value="data.realm" @change="patch({realm:value($event) as BestiaryData['realm'],archetypeId:catalog.archetypes.find(a=>a.realm===value($event))!.id,attacks:[],equipment:''})"><option value="realite">Réalité</option><option value="verite">Vérité</option></select></label><label>Difficulté indicative<select :value="data.difficultyId" @change="patch({difficultyId:value($event)})"><option v-for="d in catalog.difficulties" :key="d.id" :value="d.id">{{ d.name }}</option></select></label><label>Archétype<select :value="data.archetypeId" @change="patch({archetypeId:value($event)})"><option v-for="a in catalog.archetypes.filter(a=>a.realm===data.realm)" :key="a.id" :value="a.id">{{ a.name }}</option></select></label><label>Rôle<input :value="data.role" maxlength="160" @input="patch({role:value($event)})" /></label></div><label>Description<textarea :value="data.description" rows="2" maxlength="3000" @input="patch({description:value($event)})" /></label><label>Accroche MJ<textarea :value="data.hook" rows="2" maxlength="2000" @input="patch({hook:value($event)})" /></label><label>Tags (un par ligne)<textarea :value="data.tags.join('\n')" rows="2" @change="list('tags',$event)" /></label></template><template v-else><h3>{{ data.name }}</h3><p>{{ data.realm==='realite'?'Réalité':'Vérité' }} · {{ catalog.difficulties.find(d=>d.id===data.difficultyId)?.name }} · {{ data.role }}</p><p v-if="data.description">{{ data.description }}</p><p v-if="data.hook">{{ data.hook }}</p></template></div>
  <div class="card"><h4>Bloc de combat réduit</h4><p v-if="editable">Les plages sont indicatives : ajuste chaque valeur selon la scène. Les bonus de forme déjà compris dans ce bloc ne se rajoutent pas.</p><div class="stats"><div v-for="k in BESTIARY_STAT_KEYS" :key="k"><label v-if="editable">{{ labels[k] }} <small v-if="ranges">{{ ranges[k].min }}–{{ ranges[k].max }}</small><input :value="data.stats[k]" type="number" :min="k==='armor'?0:1" :max="k==='pv'?500:k==='armor'?30:k==='actions'?8:k==='movement'?60:50" step="1" required @input="stat(k,$event)" /></label><template v-else><small>{{ labels[k] }}</small><strong>{{ k==='initiative'||k==='perception'||k==='mastery'?'1d10e + ':'' }}{{ data.stats[k] }}</strong></template></div></div><small>Défenses actives : défense indiquée + 1d10e.</small></div>
  <div class="card"><h4>Attaques</h4><div v-for="(a,i) in data.attacks" :key="i" class="attack"><template v-if="editable"><div v-if="data.realm==='realite'" class="grid"><label>Type d’arme<select :value="catalog.weapons.find(w=>w.id===a.weaponId)?.group||'Aucune'" @change="group(i,value($event))"><option value="Aucune">Naturelle ou personnalisée</option><option v-for="g in [...new Set(catalog.weapons.map(w=>w.group))]" :key="g" :value="g">{{ g }}</option></select></label><label>Arme du catalogue<select :value="a.weaponId" @change="weapon(i,value($event))"><option value="">Personnalisée</option><option v-for="w in catalog.weapons" :key="w.id" :value="w.id">{{ w.group }} · {{ w.name }} · DGT {{ w.damage }}</option></select></label></div><div class="grid"><label>Nom<input :value="a.name" maxlength="120" :disabled="!!a.weaponId" @input="attack(i,{name:value($event)})" /></label><label>Jet (+ 1d10e)<input :value="a.score" type="number" min="1" max="50" @input="attack(i,{score:Number(value($event))})" /></label><label>DGT<input :value="a.damage" type="number" min="0" max="100" :disabled="!!a.weaponId" @input="attack(i,{damage:Number(value($event))})" /></label><label>Portée<input :value="a.range" maxlength="120" :disabled="!!a.weaponId" @input="attack(i,{range:value($event)})" /></label></div><label>Propriétés<input :value="a.properties" maxlength="300" :disabled="!!a.weaponId" @input="attack(i,{properties:value($event)})" /></label><button type="button" @click="patch({attacks:data.attacks.filter((_,n)=>n!==i)})">Retirer l’attaque</button></template><p v-else>{{ a.name }} — 1d10e + {{ a.score }} · DGT {{ a.damage }} · {{ a.range }}{{ a.properties?' · '+a.properties:'' }}</p></div><button v-if="editable&&data.attacks.length<3" type="button" @click="patch({attacks:[...data.attacks,{name:'Nouvelle attaque',score:data.stats.attack,damage:2,range:'Contact',properties:'',weaponId:''}]})">Ajouter une attaque</button><label v-if="editable&&data.realm==='realite'">Autre équipement<textarea :value="data.equipment" maxlength="1000" rows="2" @input="patch({equipment:value($event)})" /></label><p v-else-if="data.equipment">Équipement : {{ data.equipment }}</p></div>
  <div class="card"><h4>Capacités et faiblesses</h4><template v-if="editable"><label>Capacités / comportement (une par ligne)<textarea :value="data.abilities.join('\n')" rows="3" @change="list('abilities',$event)" /></label><label>Faiblesses / limites (une par ligne)<textarea :value="data.weaknesses.join('\n')" rows="3" @change="list('weaknesses',$event)" /></label></template><template v-else><p v-for="(ability,i) in data.abilities" :key="'a'+i">{{ ability }}</p><p v-for="(weakness,i) in data.weaknesses" :key="'w'+i">Faiblesse : {{ weakness }}</p></template></div>
  <ul v-if="editable&&issues.length" role="alert"><li v-for="issue in issues" :key="issue">{{ issue }}</li></ul>
 </div>
</template>
<style scoped>
.creature-sheet{display:grid;gap:14px;min-width:0}.card{display:grid;gap:12px;padding:16px;background:#101e30;border:1px solid #405875;border-radius:7px}.card h4,.card p{margin:0}.card p{line-height:1.6}.card label{display:grid;gap:7px}.card input,.card select,.card textarea{box-sizing:border-box;width:100%;min-width:0;min-height:44px;padding:10px;background:#08131f;color:#edf4ff;border:1px solid #405875;border-radius:6px;font:inherit}.card textarea{resize:vertical}.card button{padding:10px;min-height:44px;background:#172c40;color:#eaf2ff;border:1px solid #405875;border-radius:6px;cursor:pointer}.grid,.stats{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px}.stats>div,.attack{padding:10px;border:1px solid #304c62;border-radius:6px}.stats strong,.stats small{display:block}.attack{display:grid;gap:10px}small{color:#a3b7cc}button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible{outline:2px solid #a3eaff;outline-offset:3px}
</style>
